 FS03:{accent:'#71f248',glow:'#c5ff5d',shadow:'#0b4539',figure:'Broly',url:'https://en.dragon-ball-official.com/dragonball/jp/news/2024/02/t240216274-4.jpg?_=1773925380',size:'512px 512px',pos:'-42px -260px'},
 FS04:{accent:'#c88aff',glow:'#ffd963',shadow:'#412065',figure:'Frieza',url:'https://en.dragon-ball-official.com/dragonball/jp/news/2024/02/t240216274-4.jpg?_=1773925380',size:'512px 512px',pos:'-299px -260px'},
 FS05:{accent:'#ff70a3',glow:'#9b6bef',shadow:'#4c1941',figure:'Bardock',url:'https://www.breakthecase.de/cdn/shop/files/00340434636747979837_8.png?v=1751116933&width=2048',size:'512px 512px',pos:'-6px -252px'},
 FS06:{accent:'#ff5879',glow:'#ffa0e2',shadow:'#51142c',figure:'Son Goku (Mini)',url:'https://www.breakthecase.de/cdn/shop/files/00340434636747979837_8.png?v=1751116933&width=2048',size:'512px 512px',pos:'-126px -252px'},
